@push('scripts')<script>document.addEventListener('hris:ready',()=>{const table=document.querySelector('#wfh-table'),reports=document.querySelector('#wfh-reports-table'),form=document.querySelector('#wfh-form'),review=document.querySelector('#wfh-review-form');const refresh=()=>{table.table.load();reports.table.load()};[form,review,document.querySelector('#wfh-consolidate-form')].forEach(form=>HRIS.bindForm(form,{success:refresh}));document.querySelector('#new-wfh').onclick=()=>{HRIS.fillForm(form,{});form.dataset.endpoint='/wfh-accomplishments';form.dataset.method='POST';HRIS.openModal('wfh-editor')};table.addEventListener('table:action',async({detail:{action,row}})=>{try{if(action==='details'){HRIS.showDetails('Accomplishment',row);return}if(action==='edit'){HRIS.fillForm(form,row);form.dataset.endpoint=`/wfh-accomplishments/${row.id}`;form.dataset.method='PUT';HRIS.openModal('wfh-editor')}else if(action==='review'){HRIS.fillForm(review,{});review.dataset.endpoint=`/wfh-accomplishments/${row.id}/transition`;HRIS.openModal('wfh-review')}else if(await HRIS.confirm('Delete this pending accomplishment?')){HRIS.feedback((await HRIS.request(`/wfh-accomplishments/${row.id}/transition`,{method:'POST',body:{action:'delete'}})).message);refresh()}}catch(error){HRIS.feedback(error.message,true)}});reports.addEventListener('table:action',async({detail:{action,row}})=>{if(action==='print'){window.open(`/wfh-accomplishments/reports/${row.id}/print`,'_blank','noopener');return}try{if(await HRIS.confirm(`Record ${action} for this division report?`)){HRIS.feedback((await HRIS.request(`/wfh-accomplishments/reports/${row.id}/transition`,{method:'POST',body:{action}})).message);refresh()}}catch(error){HRIS.feedback(error.message,true)}});document.querySelector('#wfh-agency-form')?.addEventListener('submit',event=>{event.preventDefault();window.open(`/wfh-accomplishments/agency/${document.querySelector('#agency-date').value}/print`,'_blank','noopener')})});</script>@endpush
